-- Synthetic-only production verification. Never read existing sessions or personal data.
-- All seed rows, session hashes, contacts and bookings are rolled back; no notifications sent.
begin;
create temporary table inkorg85_checks(label text primary key) on commit drop;
grant insert,select on inkorg85_checks to anon,authenticated,service_role;
create or replace function pg_temp.check85(label text,ok boolean) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Inkorg85 assertion failed: %',label;end if;insert into inkorg85_checks values(label);end$$;
create or replace function pg_temp.deny85(label text,t text,act text,data jsonb,code text) returns void language plpgsql as $$begin begin perform public.mailbox_v2(t,act,data);exception when others then if sqlstate=code then perform pg_temp.check85(label,true);return;end if;raise;end;raise exception 'Unexpected allow: %',label;end$$;
grant execute on function pg_temp.check85(text,boolean),pg_temp.deny85(text,text,text,jsonb,text) to anon,authenticated,service_role;
create or replace function pg_temp.bulk86(t text, adm boolean,op text,k text,i bigint) returns jsonb language sql as $$select public.mailbox_v2(t,'bulk_preferences',jsonb_build_object('admin',adm,'operation',op,'items',jsonb_build_array(jsonb_build_object('kind',k,'id',i))))$$;
grant execute on function pg_temp.bulk86(text,boolean,text,text,bigint) to anon,authenticated,service_role;
do $verify$
declare prefix text:='__inkorg85_verify__';r text;tok text;drv text;adm text;own text;sup text;peer text;other text;foreign_tok text;cid1 bigint;cid2 bigint;rid bigint;wid bigint;life bigint;purge1 bigint;purge2 bigint;lb bigint;thread1 bigint;bid bigint;j jsonb;k jsonb;d text:=to_char(current_date+7,'YYYY-MM-DD');
begin
 if exists(select 1 from public.drivers where id like prefix||'%') then raise exception 'Synthetic ID collision';end if;
 insert into public.companies(id,name) values(prefix||'a','Inkorg synthetic A'),(prefix||'b','Inkorg synthetic B'),(prefix||'c','Inkorg synthetic C');
 foreach r in array array['driver','peer','admin','owner','super','other','foreign'] loop
  insert into public.drivers(id,name,first_name,last_name,category,activated,phone) values(prefix||r,'Synthetic verification','Synthetic','Verification',case r when 'admin' then 'admin' when 'owner' then 'agare' when 'super' then 'superadmin' else 'standard' end,true,'synthetic-private');
  insert into private.company_members(driver_id,company_id) values(prefix||r,prefix||case r when 'other' then 'b' when 'foreign' then 'c' else 'a' end);
  insert into private.feature_flags(feature,driver_id) values('sjuk',prefix||r);
  tok:=gen_random_uuid()::text||gen_random_uuid()::text;
  insert into private.sessions(token_hash,driver_id,via_master,expires_at) values(private.token_hash(tok),prefix||r,false,now()+interval '2 days');
  case r when 'driver' then drv:=tok;when 'peer' then peer:=tok;when 'admin' then adm:=tok;when 'owner' then own:=tok;when 'super' then sup:=tok;when 'other' then other:=tok;else foreign_tok:=tok;end case;
 end loop;
 insert into inbox_private.bolag values(prefix||'same','Synthetic bolag'),(prefix||'different','Different synthetic bolag');
 insert into inbox_private.operator_companies values(prefix||'a',prefix||'same'),(prefix||'b',prefix||'same'),(prefix||'c',prefix||'different');
 insert into public.cars(company_id,bilnummer,modell,kategorier) values(prefix||'a','25','Synthetic','{Sedan}') returning id into cid1;
 insert into public.cars(company_id,bilnummer,modell,kategorier) values(prefix||'b','7','Synthetic','{Sedan}') returning id into cid2;
 insert into private.sick_reports(driver_id,start_date,status,sjuklon) values(prefix||'driver',current_date,'ny','ej') returning id into rid;
 insert into private.sick_certs(report_id,path,mime,uploaded,uploaded_by) values(rid,prefix||'synthetic-not-a-file.pdf','application/pdf',true,prefix||'driver');
 insert into public.workshop_hours(driver_id,start_at,end_at,car_id,car_label,status) values(prefix||'driver',now(),now()+interval '1 hour',cid1,'Synthetic','pending') returning id into wid;
 execute 'set local role anon';
 perform pg_temp.check85('driver valid role',jsonb_typeof(public.mailbox_v2(drv,'list'))='array');
 perform pg_temp.check85('admin valid role',jsonb_typeof(public.mailbox_v2(adm,'list','{"admin":true}'))='array');
 perform pg_temp.check85('owner valid role',public.mailbox_v2(own,'list')='[]');
 perform pg_temp.check85('superadmin valid role',public.mailbox_v2(sup,'list')='[]');
 perform pg_temp.deny85('driver cannot request admin',drv,'list','{"admin":true}','42501');
 perform pg_temp.deny85('bad session rejected','invalid-inkorg85-session','list','{}','28000');
 perform pg_temp.check85('own sickness visible',(public.case_get(drv,'sjuk',rid)->>'id')::bigint=rid);
 begin perform public.case_get(adm,'sjuk',rid);raise exception 'Admin sickness leak';exception when insufficient_privilege then perform pg_temp.check85('admin cannot see another sickness',true);end;
 begin perform public.case_get(peer,'sjuk',rid);raise exception 'Peer sickness leak';exception when insufficient_privilege then perform pg_temp.check85('peer cannot see another sickness',true);end;
 perform pg_temp.check85('owner sickness visible',(public.case_get(own,'sjuk',rid)->>'id')::bigint=rid);
 perform pg_temp.check85('temporary superadmin sickness visible',(public.case_get(sup,'sjuk',rid)->>'id')::bigint=rid);
 j:=public.case_admin_list(adm);perform pg_temp.check85('admin sickness excluded from list',not exists(select 1 from jsonb_array_elements(j->'items') x where x->>'kind'='sjuk'));
 perform pg_temp.check85('owner no personal cases',jsonb_array_length(public.case_inbox(own)->'items')=0);
 perform pg_temp.check85('private phone default hidden',public.mailbox_v2(peer,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone' is null);
 perform pg_temp.check85('owner sees contact phone',public.mailbox_v2(own,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone'='synthetic-private');
 perform pg_temp.check85('super sees contact phone',public.mailbox_v2(sup,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone'='synthetic-private');
 perform pg_temp.check85('admin phone hidden by default',public.mailbox_v2(adm,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone' is null);
 perform public.mailbox_v2(drv,'contacts_save','{"visibility":"company","cars":["25","7"]}');
 perform pg_temp.check85('akeri phone shared',public.mailbox_v2(peer,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone'='synthetic-private');
 perform pg_temp.check85('akeri phone hidden outside',public.mailbox_v2(other,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone' is null);
 perform public.mailbox_v2(drv,'contacts_save','{"visibility":"bolag"}');
 perform pg_temp.check85('same bolag phone shared',public.mailbox_v2(other,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone'='synthetic-private');
 perform pg_temp.check85('different bolag phone hidden',public.mailbox_v2(foreign_tok,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'))->>'phone' is null);
 perform public.mailbox_v2(drv,'contacts_save','{"visibility":"owner"}');
 j:=public.mailbox_v2(peer,'contacts_get',jsonb_build_object('driver_id',prefix||'driver'));
 perform pg_temp.check85('car phones remain visible with private phone hidden',jsonb_array_length(j->'cars')=2 and j->>'phone' is null);
 perform pg_temp.check85('fleet list scoped',jsonb_array_length(public.mailbox_v2(drv,'cars'))=1);
 perform pg_temp.deny85('missing car selection rejected',drv,'create','{"subject":"Synthetic","body":"Synthetic"}','22023');
 perform pg_temp.deny85('foreign fleet car rejected',drv,'create',jsonb_build_object('subject','Synthetic','body','Synthetic','car_choice',cid2::text),'22023');
 j:=public.mailbox_v2(drv,'create',jsonb_build_object('subject','Synthetic transaction verification','body','Synthetic rollback only','car_choice',cid1::text));thread1:=(j->>'id')::bigint;
 perform pg_temp.check85('last sender role exposed',public.mailbox_v2(adm,'list','{"admin":true}')->0->>'last_sender_role'='driver');
 perform public.mailbox_v2(adm,'mark_unread',jsonb_build_object('admin',true,'kind','thread','id',thread1));
 perform pg_temp.check85('manual unread own user only',jsonb_array_length(public.mailbox_v2(adm,'unread_flags','{"admin":true}'))=1 and public.mailbox_v2(drv,'unread_flags')='[]');
 perform public.mailbox_v2(adm,'mark_read',jsonb_build_object('admin',true,'kind','thread','id',thread1));
 perform pg_temp.check85('manual unread clears on open',public.mailbox_v2(adm,'unread_flags','{"admin":true}')='[]');
 perform pg_temp.deny85('peer cannot mark other thread unread',peer,'mark_unread',jsonb_build_object('kind','thread','id',thread1),'P0002');
 perform pg_temp.deny85('foreign company cannot mark thread unread',foreign_tok,'mark_unread',jsonb_build_object('kind','thread','id',thread1),'P0002');
 perform pg_temp.deny85('admin cannot mark secret sickness unread',adm,'mark_unread',jsonb_build_object('admin',true,'kind','sjuk','id',rid),'42501');
 perform public.mailbox_v2(drv,'mark_unread',jsonb_build_object('kind','sjuk','id',rid));
 perform pg_temp.check85('own sickness manual unread allowed',jsonb_array_length(public.mailbox_v2(drv,'unread_flags'))=1);
 perform public.mailbox_v2(drv,'mark_read',jsonb_build_object('kind','sjuk','id',rid));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));
 perform pg_temp.check85('verified fleet link stored',(j->>'car_id')::bigint=cid1 and j->>'car_number'='25');
 perform pg_temp.check85('admin sees driver thread',jsonb_array_length(public.mailbox_v2(adm,'list','{"admin":true}'))=1);
 perform pg_temp.deny85('another driver thread denied',peer,'get',jsonb_build_object('thread_id',thread1),'P0002');
 perform pg_temp.deny85('booking missing selection rejected',drv,'book',jsonb_build_object('thread_id',thread1,'kind','Synthetic service','date',d,'time','09:30'),'22023');
 perform pg_temp.deny85('booking foreign car rejected',drv,'book',jsonb_build_object('thread_id',thread1,'kind','Synthetic service','date',d,'time','09:30','car_choice',cid2::text),'22023');
 perform public.mailbox_v2(drv,'book',jsonb_build_object('thread_id',thread1,'kind','Synthetic service','date',d,'time','09:30','car_choice','none','body','Synthetic booking message'));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));k:=j->'bookings'->0;bid:=(k->>'id')::bigint;
 perform pg_temp.check85('pending booking state in list',public.mailbox_v2(adm,'list','{"admin":true}')->0->'booking_states' ? 'pending_admin');
 perform pg_temp.check85('driver proposal pending admin',k->>'status'='pending_admin' and k->>'car_id' is null);
 perform pg_temp.check85('booking optional text in history',exists(select 1 from jsonb_array_elements(j->'messages') x where x->>'body'='Synthetic booking message'));
 perform pg_temp.deny85('proposer cannot self approve',drv,'decide',jsonb_build_object('booking_id',bid,'decision','accepted'),'42501');
 perform public.mailbox_v2(adm,'decide',jsonb_build_object('admin',true,'booking_id',bid,'decision','accepted'));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));
 perform pg_temp.check85('admin accepted driver proposal',j->'bookings'->0->>'status'='accepted');
 perform public.mailbox_v2(adm,'book',jsonb_build_object('admin',true,'thread_id',thread1,'kind','Synthetic admin booking','date',d,'time','14:05','car_choice',cid1::text));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));bid:=(j->'bookings'->1->>'id')::bigint;
 perform pg_temp.check85('admin proposal pending driver',j->'bookings'->1->>'status'='pending_driver');
 perform pg_temp.deny85('decline requires reason',drv,'decide',jsonb_build_object('booking_id',bid,'decision','declined','reason',''),'22023');
 perform pg_temp.deny85('decline whitespace rejected',drv,'decide',jsonb_build_object('booking_id',bid,'decision','declined','reason',E' \n\t'),'22023');
 perform public.mailbox_v2(drv,'decide',jsonb_build_object('booking_id',bid,'decision','declined','reason','Synthetic reason'));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));
 perform pg_temp.check85('driver declined admin booking',j->'bookings'->1->>'status'='declined');
 perform pg_temp.check85('decline reason not mistaken for unanswered reply',(public.mailbox_v2(adm,'list','{"admin":true}')->0->>'decision_reply')::boolean);
 perform pg_temp.check85('reason saved as normal reply',exists(select 1 from jsonb_array_elements(j->'messages') x where x->>'body'='Synthetic reason' and x->>'role'='driver'));
 perform pg_temp.check85('declined removed from timeline',jsonb_array_length(public.mailbox_v2(drv,'timeline'))=1);
 perform public.mailbox_v2(adm,'book',jsonb_build_object('admin',true,'thread_id',thread1,'kind','Synthetic accepted booking','date',d,'time','15:00','car_choice','none'));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));bid:=(j->'bookings'->2->>'id')::bigint;
 perform public.mailbox_v2(drv,'decide',jsonb_build_object('booking_id',bid,'decision','accepted'));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',thread1));
 perform pg_temp.check85('driver accepted admin booking',j->'bookings'->2->>'status'='accepted');
 begin perform count(*) from inbox_private.threads;raise exception 'Direct storage exposed';exception when insufficient_privilege then perform pg_temp.check85('direct tables denied',true);end;

 -- PR86: all four role capabilities; temporary superadmin follows existing central switch.
 perform pg_temp.check85('driver no trash',not (public.mailbox_v2(drv,'mailbox_capabilities')->>'can_trash')::boolean);
 perform pg_temp.check85('admin no trash',not (public.mailbox_v2(adm,'mailbox_capabilities','{"admin":true}')->>'can_trash')::boolean);
 perform pg_temp.check85('owner trash allowed',(public.mailbox_v2(own,'mailbox_capabilities','{"admin":true}')->>'can_trash')::boolean);
 perform pg_temp.check85('temporary superadmin trash allowed',(public.mailbox_v2(sup,'mailbox_capabilities','{"admin":true}')->>'can_trash')::boolean);
 perform pg_temp.check85('medical hard delete disabled',not (public.mailbox_v2(own,'mailbox_capabilities','{"admin":true}')->>'secret_hard_delete_enabled')::boolean);
 life:=(public.mailbox_v2(drv,'create','{"subject":"Synthetic PR86 lifecycle","body":"Whole original history","car_choice":"none"}')->>'id')::bigint;
 perform pg_temp.bulk86(drv,false,'pin','thread',life);
 perform pg_temp.check85('personal pin',exists(select 1 from jsonb_array_elements(public.mailbox_v2(drv,'item_flags')) x where (x->>'id')::bigint=life and (x->>'pinned')::boolean));
 perform pg_temp.check85('pin not shared',public.mailbox_v2(own,'item_flags','{"admin":true}')='[]');
 perform pg_temp.bulk86(drv,false,'unread','thread',life);
 perform pg_temp.check85('manual unread remains available',exists(select 1 from jsonb_array_elements(public.mailbox_v2(drv,'item_flags')) x where (x->>'id')::bigint=life and (x->>'is_unread')::boolean));
 perform pg_temp.bulk86(drv,false,'hide','thread',life);
 perform pg_temp.check85('driver hidden only',exists(select 1 from jsonb_array_elements(public.mailbox_v2(drv,'item_flags')) x where (x->>'id')::bigint=life and (x->>'hidden')::boolean));
 perform pg_temp.check85('driver deletion leaves admin copy',(public.mailbox_v2(adm,'get',jsonb_build_object('admin',true,'thread_id',life))->>'id')::bigint=life);
 perform public.mailbox_v2(adm,'reply',jsonb_build_object('admin',true,'thread_id',life,'body','Synthetic admin resurrection'));
 perform pg_temp.check85('admin reply clears driver hide',not exists(select 1 from jsonb_array_elements(public.mailbox_v2(drv,'item_flags')) x where (x->>'id')::bigint=life and (x->>'hidden')::boolean));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',life));
 perform pg_temp.check85('whole original history resurrected',jsonb_array_length(j->'messages')=2 and j->'messages'->0->>'body'='Whole original history');
 perform public.mailbox_v2(adm,'book',jsonb_build_object('admin',true,'thread_id',life,'kind','Synthetic lock booking','date',d,'time','19:00','car_choice','none'));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',life));lb:=(j->'bookings'->0->>'id')::bigint;
 perform pg_temp.bulk86(adm,true,'hide','thread',life);
 perform pg_temp.check85('admin deletes into owner trash',exists(select 1 from jsonb_array_elements(public.mailbox_v2(own,'item_flags','{"admin":true}')) x where (x->>'id')::bigint=life and (x->>'in_trash')::boolean));
 j:=public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',life));
 perform pg_temp.check85('trashed thread readable and locked',(j->>'locked')::boolean and j->'messages'->0->>'body'='Whole original history');
 perform pg_temp.deny85('locked RPC rejects reply',drv,'reply',jsonb_build_object('thread_id',life,'body','Blocked'),'42501');
 perform pg_temp.deny85('locked RPC rejects booking',drv,'book',jsonb_build_object('thread_id',life,'kind','Blocked','date',d,'time','20:00','car_choice','none'),'42501');
 perform pg_temp.deny85('locked RPC rejects acceptance',drv,'decide',jsonb_build_object('booking_id',lb,'decision','accepted'),'42501');
 perform pg_temp.deny85('ordinary admin cannot restore',adm,'bulk_preferences',jsonb_build_object('admin',true,'operation','restore','items',jsonb_build_array(jsonb_build_object('kind','thread','id',life))),'42501');
 perform pg_temp.deny85('driver cannot restore',drv,'bulk_preferences',jsonb_build_object('operation','restore','items',jsonb_build_array(jsonb_build_object('kind','thread','id',life))),'42501');
 perform pg_temp.bulk86(own,true,'restore','thread',life);
 perform pg_temp.check85('owner restore unlocks',not (public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',life))->>'locked')::boolean);
 perform public.mailbox_v2(drv,'reply',jsonb_build_object('thread_id',life,'body','Unlocked response'));
 perform pg_temp.check85('restored driver reply works',public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',life))->'messages'->-1->>'body'='Unlocked response');
 perform pg_temp.bulk86(adm,true,'hide','thread',life);perform pg_temp.bulk86(own,true,'permanent','thread',life);
 perform pg_temp.check85('permanent leaves locked driver copy',(public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',life))->>'locked')::boolean);
 perform pg_temp.deny85('permanent driver reply denied',drv,'reply',jsonb_build_object('thread_id',life,'body','Blocked'),'42501');
 perform pg_temp.deny85('permanent admin reply denied',adm,'reply',jsonb_build_object('admin',true,'thread_id',life,'body','Blocked'),'42501');
 perform pg_temp.bulk86(drv,false,'hide','thread',life);
 perform pg_temp.deny85('owner then driver deletion physically removes thread',drv,'get',jsonb_build_object('thread_id',life),'P0002');
 purge2:=(public.mailbox_v2(drv,'create','{"subject":"Synthetic PR86 reverse","body":"Synthetic reverse order","car_choice":"none"}')->>'id')::bigint;
 perform pg_temp.bulk86(drv,false,'hide','thread',purge2);
 perform pg_temp.check85('driver first still leaves owner copy',(public.mailbox_v2(own,'get',jsonb_build_object('admin',true,'thread_id',purge2))->>'id')::bigint=purge2);
 perform pg_temp.bulk86(adm,true,'hide','thread',purge2);perform pg_temp.bulk86(sup,true,'restore','thread',purge2);
 perform pg_temp.check85('temporary superadmin can restore',not (public.mailbox_v2(drv,'get',jsonb_build_object('thread_id',purge2))->>'locked')::boolean);
 perform pg_temp.bulk86(adm,true,'hide','thread',purge2);perform pg_temp.bulk86(own,true,'permanent','thread',purge2);
 perform pg_temp.deny85('driver then owner deletion physically removes thread',drv,'get',jsonb_build_object('thread_id',purge2),'P0002');
 perform pg_temp.deny85('foreign company cannot pin',foreign_tok,'bulk_preferences',jsonb_build_object('operation','pin','items',jsonb_build_array(jsonb_build_object('kind','thread','id',thread1))),'P0002');
 perform pg_temp.bulk86(drv,false,'hide','wh',wid);
 -- Existing legacy RPC: guard runs before notification or message insert.
 perform public.workshop_ask(adm,wid,'Synthetic legacy admin reply');
 perform pg_temp.check85('legacy admin reply clears driver hide',not exists(select 1 from jsonb_array_elements(public.mailbox_v2(drv,'item_flags')) x where x->>'kind'='wh' and (x->>'id')::bigint=wid and (x->>'hidden')::boolean));
 perform pg_temp.bulk86(adm,true,'hide','wh',wid);
 begin perform public.workshop_reply(drv,wid,'Blocked legacy reply');raise exception 'Legacy lock bypass';exception when insufficient_privilege then perform pg_temp.check85('legacy workshop RPC lock enforced',true);end;
 perform pg_temp.bulk86(own,true,'restore','wh',wid);perform public.workshop_reply(drv,wid,'Synthetic unlocked legacy reply');
 perform pg_temp.check85('legacy restored unlock',not (public.mailbox_v2(drv,'item_lock',jsonb_build_object('kind','wh','id',wid))->>'locked')::boolean);
 perform pg_temp.bulk86(drv,false,'hide','sjuk',rid);perform pg_temp.bulk86(own,true,'hide','sjuk',rid);perform pg_temp.bulk86(own,true,'permanent','sjuk',rid);
 perform pg_temp.check85('medical record remains physically readable',(public.case_get(drv,'sjuk',rid)->>'id')::bigint=rid);
 execute 'reset role';
 execute 'set local role service_role';
 begin perform public.sjuk_svc_cert_list(adm,rid);raise exception 'Admin certificate leak';exception when insufficient_privilege then perform pg_temp.check85('admin certificate denied',true);end;
 perform pg_temp.check85('owner certificate permitted',jsonb_array_length(public.sjuk_svc_cert_list(own,rid))=1);
 perform pg_temp.check85('temporary superadmin certificate permitted',jsonb_array_length(public.sjuk_svc_cert_list(sup,rid))=1);
 perform pg_temp.check85('driver own certificate permitted',jsonb_array_length(public.sjuk_svc_cert_list(drv,rid))=1);
 execute 'reset role';
 perform pg_temp.check85('all checks completed',(select count(*) from inkorg85_checks)>=40);
end $verify$;
rollback;
select 'PASS PR86: resurrection, locks, restores, both deletion orders, four roles, pin/unread, medical retention; real production RPC implementations, anon/service_role callers, driver/admin/owner/superadmin, phone company/bolag boundaries, bookings and fleet validation. All synthetic rows and sessions rolled back.' as verification;
